// Bundles the website's own room cores (rules and bots) with the app's offline plumbing (rules/offline.js) into one
// file the app runs in JavaScriptCore (#402), and writes the parity fixture: the same seeded games played in Node.
// Nothing here is rules; the rules come from the website, copied by this build, never written twice by hand.
//   node scripts/rules-bundle.mjs ../tyleralocke          (re-run whenever the website's game rules change)
//   node scripts/rules-bundle.mjs ../tyleralocke --check  (exit 1 if the bundled rules are out of date)
import { createRequire } from 'node:module';
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';
import { createHash } from 'node:crypto';
import vm from 'node:vm';

const site = resolve(process.argv[2] || '../tyleralocke');
const check = process.argv.includes('--check');
const out = resolve('Core/Sources/T2PCore/Resources/rules.js');
const fixture = resolve('Core/Tests/T2PCoreTests/Fixtures/parity.json');
const esbuild = createRequire(`${site}/package.json`)('esbuild');

const SOURCES = ['src/live/overdraft/room-core.cjs', 'src/live/overdraft/engine.cjs', 'src/live/overdraft/bots.cjs', 'src/live/farkle/room-core.js',
	'src/games/farkle/scoring.js', 'src/live/rollcall/room-core.js', 'src/live/rollcall/rules.js', 'src/live/closeenough/room-core.js', 'src/live/closeenough/questions.js'];
const sha = (s) => createHash('sha256').update(s).digest('hex').slice(0, 16);
const sources = SOURCES.map((f) => `//   ${f} ${sha(readFileSync(`${site}/${f}`))}`).join('\n');
let commit = 'unknown';
try { commit = execFileSync('git', ['-C', site, 'rev-parse', '--short', 'HEAD']).toString().trim(); } catch {}

const built = await esbuild.build({
	entryPoints: [resolve('rules/offline.js')], bundle: true, write: false, format: 'iife', target: 'es2020', platform: 'neutral',
	mainFields: ['module', 'main'], alias: { '@site': site }, legalComments: 'none', minify: false
});
const body = built.outputFiles[0].text;
const header = `// GENERATED by scripts/rules-bundle.mjs: do not edit. The website's room cores (rules and bots) and the app's
// offline plumbing (rules/offline.js), for offline games in JavaScriptCore (#402). From wayloncore/tyleralocke
// at the files below (sha-256, first 16 hex):
${sources}
`;
const text = header + body;

// The parity runs, in a bare context like JavaScriptCore's (no require, module, crypto or timers)
const ctx = vm.createContext({});
vm.runInContext(body, ctx);
const games = [['overdraft', 7], ['overdraft', 1234], ['farkle', 7], ['farkle', 99], ['rollcall', 7], ['closeenough', 7]];
const runs = games.map(([g, s]) => JSON.parse(ctx.T2POffline.parity(g, s)));
for (const r of runs) if (r.phase !== 'done') console.warn(`parity: ${r.game} seed ${r.seed} stopped at ${r.phase} after ${r.steps} steps`);
const fixtureText = JSON.stringify({ sources: header.split('\n').filter((l) => l.startsWith('//   ')).map((l) => l.slice(5)), runs }, null, 1) + '\n';

if (check) {
	const same = existsSync(out) && readFileSync(out, 'utf8').split('\n').filter((l) => l.startsWith('//   ')).join('\n') === sources;
	console.log(same ? 'rules.js matches the website’s rules' : 'rules.js is OUT OF DATE: run node scripts/rules-bundle.mjs ../tyleralocke');
	process.exit(same ? 0 : 1);
}
writeFileSync(out, text);
writeFileSync(fixture, fixtureText);
console.log(`rules.js ${Math.round(text.length / 1024)} KB from ${commit}; parity: ${runs.map((r) => `${r.game}/${r.seed} ${r.steps} steps ${r.phase}`).join(', ')}`);
